-- M12.2 lists: blocklists and canary sets as Register sources, read by one adapter
-- (src/adapters/blocklists.ts). Each list is a document whose entries are its requirements,
-- diffed line by line, so the list's next release is a diff with a date like any standard.
-- Nothing is ever fetched from a name on a list: the lists are documents read from their
-- publishers, and canary names are only ever resolved, never loaded, and never linked.
-- OpenPhish's Community Feed terms forbid commercial use and any redistribution, derivative
-- work or display to third parties, so that set is registered off; a private instance's owner
-- may turn the row on by hand.

INSERT OR IGNORE INTO sources (id, name, kind, group_name, url, format, schedule, enabled, licence, attribution, notes) VALUES
('adfection-indicators', 'AdFection / Candiru indicators (Zero Breach)', 'requirement-set', 'standards', 'https://github.com/interplains/zero-breach/blob/main/iocs/adfection_iocs.txt', 'text', 'daily', 1, 'CC0 1.0 (the indicator data); the Zero Breach software is Apache-2.0', 'Indicators curated by the Zero Breach project (archivegenocide.com) from The Citizen Lab, Confiant, Recorded Future, Microsoft, ESET, Avast, Google TAG and Amnesty International reports; the project is not affiliated with or endorsed by any of them.', 'The AdFection / Candiru indicator list: every domain, address and file hash with its tier (command-and-control, validator, ad delivery, historical, sample, abused driver), its confidence and the report it was read from, one line each. The current commit is read from the GitHub API, and the commit''s first line is the release''s reason. Indicators are quoted, never fetched and never linked.'),
('adfection-dns', 'AdFection / Candiru DNS blocklist (Zero Breach)', 'requirement-set', 'standards', 'https://github.com/interplains/zero-breach/blob/main/dist/adfection.domains.txt', 'text', 'daily', 1, 'CC0 1.0', 'Zero Breach project (archivegenocide.com); not affiliated with or endorsed by the researchers it cites.', 'The plain-domain export of the indicator list (291 domains when added), the form a Pi-hole or AdGuard Home takes as an adlist: one requirement per domain, so a release shows which domains came and went.'),
('adfection-adblock', 'AdFection / Candiru ad blocklist (Zero Breach)', 'requirement-set', 'standards', 'https://github.com/interplains/zero-breach/blob/main/dist/adfection.adblock.txt', 'adblock', 'daily', 1, 'CC0 1.0', 'Zero Breach project (archivegenocide.com); not affiliated with or endorsed by the researchers it cites.', 'The Adblock Plus, uBlock Origin and AdGuard export of the same indicators, one ||domain^ rule each, for a browser blocker''s custom list.'),
('canary-ads', 'Ad canaries (EasyList)', 'requirement-set', 'standards', 'https://easylist.to/easylist/easylist.txt', 'adblock', 'weekly', 1, 'GPLv3 or CC BY-SA 3.0 (EasyList''s dual licence); twelve rules quoted with attribution', 'EasyList (easylist.to)', 'Twelve ad domains derived from EasyList: of the rules that block a domain outright (||domain^, with or without $third-party), the twelve whose names hash lowest under SHA-256, so nobody chose them and the set moves only when the list drops one or gains a name that hashes lower. The network check (M12.3) resolves them through the LAN resolver and does nothing else with them. Checked weekly; the list itself moves several times a day.'),
('canary-trackers', 'Tracker canaries (EasyPrivacy)', 'requirement-set', 'standards', 'https://easylist.to/easylist/easyprivacy.txt', 'adblock', 'weekly', 1, 'GPLv3 or CC BY-SA 3.0 (EasyList''s dual licence); twelve rules quoted with attribution', 'EasyPrivacy (easylist.to)', 'Twelve tracker domains derived from EasyPrivacy the same way as the ad canaries: the outright domain rules whose names hash lowest. Resolved by the network check, never loaded. Checked weekly.'),
('canary-malware', 'Malware canaries (URLhaus)', 'requirement-set', 'standards', 'https://urlhaus.abuse.ch/downloads/hostfile/', 'text', 'daily', 1, 'abuse.ch URLhaus Community data, free under its fair-use terms (https://urlhaus.abuse.ch/api/); commercial use may need the paid API', 'URLhaus by abuse.ch', 'Twelve malware-hosting names derived from URLhaus''s host file (the hosts of malware URLs online right now, the list a Pi-hole takes): registrable names only (two labels once a leading www. is dropped; no addresses, no subdomains of shared platforms), the twelve that hash lowest. Checked daily because the host file turns over as sites go offline.'),
('canary-phishing', 'Phishing canaries (OpenPhish)', 'requirement-set', 'standards', 'https://openphish.com/feed.txt', 'text', 'daily', 0, 'OpenPhish Community Feed terms: non-commercial use only; no redistribution, derivative works or display to third parties', 'OpenPhish Community Feed', 'Twelve phishing hosts derived from the OpenPhish Community Feed (refreshed every twelve hours) the same way as the malware canaries: registrable names only, the twelve that hash lowest; each entry keeps the origin alone, never a path. Registered off: OpenPhish''s terms forbid showing any part of the feed to third parties, which a public instance would do on these pages, so nothing is fetched until the owner of a private instance turns the row on by hand (sources.enabled). There is no switch in the app.');
